"}, {"id": "220d1c35-b943-449a-8a91-5a0a4aa0418f", "type": "concept", "title": "Punctuation awareness"}], "description": "Print concepts orient young readers to how books, pages, sentences, words, and directionality work."}, {"id": "4e011e94-e57d-45b2-bdde-a3ae323c8781", "type": "subtopic", "title": "Alphabet knowledge", "children": [{"id": "8c1e0b34-a2c0-4bf9-978a-8dfe75e2f619", "type": "concept", "title": "Letter recognition"}, {"id": "c3e87571-f415-4fa6-ad11-04386bcd6a0c", "type": "concept", "title": "Letter formation"}, {"id": "117c3fcf-3938-4975-b218-cf484c44ac83", "type": "concept", "title": "Uppercase and lowercase"}, {"id": "49f43232-43b0-4b8c-b6c4-1055a4d6b51a", "type": "concept", "title": "Sound-symbol associations"}], "description": "Letter names, forms, and sounds prepare students for decoding and spelling."}, {"id": "de6a8209-ace4-4219-9a07-378a254d9860", "type": "subtopic", "title": "Early handwriting and encoding", "children": [{"id": "55e78633-d1da-4ef7-92c8-7567f027f9f8", "type": "concept", "title": "Pencil grip and formation"}, {"id": "30f56a67-6fee-425c-bb16-87027e2a634e", "type": "concept", "title": "Dictation"}, {"id": "45eb8267-538d-4fec-850c-d649b2298eb4", "type": "concept", "title": "Invented spelling as data"}, {"id": "2244c5ea-122c-4dc2-a111-b7e67d555c66", "type": "concept", "title": "Encoding practice"}], "description": "Handwriting and spelling practice reinforce letter-sound learning and orthographic memory."}]}, {"id": "f72c298f-98b8-42ad-8572-efd69fa54076", "type": "topic", "title": "Systematic Phonics, Decoding, and Encoding", "description": "Design explicit phonics instruction that links graphemes, phonemes, decoding, spelling, and word reading.", "children": [{"id": "34675d50-47c6-4506-bf87-628e1154c7b9", "type": "subtopic", "title": "Phonics scope and sequence", "children": [{"id": "04c50df9-408e-4f20-a793-1e9abfda9663", "type": "concept", "title": "Short vowels"}, {"id": "ad41b162-788f-4fc0-b200-ce87468be6d1", "type": "concept", "