ing."}, {"id": "f5f2ad17-36ff-40e6-a1e4-30b38bb2dfbf", "type": "subtopic", "title": "Disciplinary and content-area literacy", "children": [{"id": "a218d1f3-109f-48d2-93c1-6e8c1e8ea7a1", "type": "concept", "title": "Disciplinary vocabulary"}, {"id": "53f0f020-c218-40d6-b284-73480cb500bd", "type": "concept", "title": "Text features"}, {"id": "e74eae0d-3ee5-47ff-a35f-e2ce568bb51f", "type": "concept", "title": "Source evaluation"}, {"id": "d2dbb0ac-5c53-4df8-8bcf-a1e515d71d45", "type": "concept", "title": "Reading and writing across content"}], "description": "Older elementary readers need literacy practices specific to science, social studies, math, and the arts."}]}, {"id": "33e3898b-9ac4-4e27-8b19-9eb344afc165", "type": "topic", "title": "Capstone Structured Literacy Unit and Reading Intervention Plan", "description": "Synthesize the course through an evidence-based unit, assessment plan, intervention cycle, and family communication plan.", "children": [{"id": "690b7e21-18f1-415c-ab21-8efdce20461d", "type": "subtopic", "title": "Structured literacy unit", "children": [{"id": "2221d8f0-373c-4878-966c-6e0933ae9068", "type": "concept", "title": "Scope and sequence rationale"}, {"id": "af292911-3ae8-4dc2-8a3d-74941108aca1", "type": "concept", "title": "Lesson sequence"}, {"id": "7e867d57-c09e-4def-943b-26b708141d7d", "type": "concept", "title": "Decodable or controlled text"}, {"id": "00120d51-0080-4a60-b245-396286dbdf92", "type": "concept", "title": "Cumulative review"}], "description": "The capstone unit asks students to design a coherent sequence grounded in reading science."}, {"id": "68590e7d-afa4-443e-9ae2-441d5648c8d7", "type": "subtopic", "title": "Assessment and intervention cycle", "children": [{"id": "ce5508c2-c0bd-4fa4-a895-2cfc47566617", "type": "concept", "title": "Screening data"}, {"id": "b165ed18-d6a2-45ec-b472-ac41849a4cd7", "type": "concept", "title": "Diagnostic interpretation"}, {"id": "1e584032-4a90-4359-97d8-7d415bdb092d", "type": "concept", "title": "Intervention goal"}, {"id": "166b1cce-0bf0-4da3-bb98-92af030ea9e4", "type": "concept", "title": "Progress monitoring plan"}], "description": "The plan must show how assessment evidence leads to targeted instruction and progress monitoring."}, {"id": "0e87205c-7f8c-4472-8f35-9ec492d34072", "type": "subtopic", "title": "Equity and family communication", "children": [{"id": "890f7fae-aeb7-4e44-907e-d6388e2fb722", "type": "concept", "title": "UDL and accommodations"}, {"id": "28b741ae-187c-4bf7-a6c9-772c75b8b24e", "type": "concept", "title": "Multilingual supports"}, {"id": "57a133d8-9c18-4348-8d6b-0ea4b2597d29", "type": "concept", "title": "Family explanation"}, {"id": "d21ebd23-6d8d-48d5-8e4d-9037fade1033", "type": "concept", "title": "Ethical reflection"}], "description": "A world-class literacy plan includes access, multilingual supports, dyslexia awareness, and clear family communication."}]}], "dbBacked": true}$folijson$::jsonb,
