update public.learning_paths
set
  title = 'Foundations of Literacy / Phonics & Reading Science',
  goal = 'Foundations of Literacy / Phonics & Reading Science',
  summary = 'Frame reading as a learned language-literacy system grounded in oral language, print, cognition, instruction, and evidence. Build the linguistic foundation teachers need for phonics, spelling, vocabulary, and comprehension; teach how children notice and connect speech sounds, print, and letter-sound patterns; design systematic and advanced phonics for decoding, spelling, syllables, and morphology; and connect fluency, vocabulary, knowledge, and comprehension to structured literacy routines, assessment, intervention, multilingual learners, writing, and a capstone reading intervention plan.',
  data = $folijson${"slug": "foundations-of-literacy-phonics-and-reading-science", "title": "Foundations of Literacy / Phonics & Reading Science", "description": "Frame reading as a learned language-literacy system grounded in oral language, print, cognition, instruction, and evidence. Build the linguistic foundation teachers need for phonics, spelling, vocabulary, and comprehension; teach how children notice and connect speech sounds, print, and letter-sound patterns; design systematic and advanced phonics for decoding, spelling, syllables, and morphology; and connect fluency, vocabulary, knowledge, and comprehension to structured literacy routines, assessment, intervention, multilingual learners, writing, and a capstone reading intervention plan.", "topics": [{"id": "303ddf49-79a9-47fc-bf61-12a38f1f7937", "type": "topic", "title": "Reading Science, Literacy Foundations, and the Reading Brain", "description": "Frame reading as a learned language-literacy system grounded in oral language, print, cognition, instruction, and evidence.", "children": [{"id": "825dfd7d-07c2-478c-b9e2-d49347ddc5ab", "type": "subtopic", "title": "Science of reading as evidence base", "children": [{"id": "15cf6ada-61ce-4b1a-af46-a7dda16cf46b", "type": "concept", "title": "Converging evidence"}, {"id": "82fdbe18-00d5-4477-8b45-90e165354201", "type": "concept", "title": "Reading as learned skill"}, {"id": "1fd54f06-83cc-4717-befb-a0d7a90baf24", "type": "concept", "title": "Alphabetic principle"}, {"id": "79860a81-d40d-474b-8c51-a1981872350f", "type": "concept", "title": "Instructional implications"}], "description": "Students learn that reading instruction should be guided by converging evidence from cognitive science, linguistics, neuroscience, and classroom research."}, {"id": "f2daaa9b-541b-43c7-9366-233edeb22f17", "type": "subtopic", "title": "Five components of reading", "children": [{"id": "21204057-9c55-4f47-8430-280e664bc521", "type": "concept", "title": "Phonemic awareness"}, {"id": 